# Generate fixtures with Julia's `Base.log1p` on the shared inputs in `../../inputs/`.
#
# Where `log1p` throws (a `DomainError` below -1), the runner writes `null` for
# `expected`, and records the exception's name in a parallel `errors` array.

import JSON
import SHA
import Dates

"""
	decode( v )

Decode a JSON value from a shared input file as a double.
"""
function decode( v )
	if v isa AbstractString
		v == "NaN" && return NaN;
		v == "Infinity" && return Inf;
		v == "-Infinity" && return -Inf;
		error( "unexpected string in inputs: $(v)" );
	end
	return Float64( v );
end

"""
	encode( x )

Encode a double as a JSON value, matching the shared input files.
"""
function encode( x::Nothing )
	return "null";
end

function encode( x::Float64 )
	isnan( x ) && return "\"NaN\"";
	x == Inf && return "\"Infinity\"";
	x == -Inf && return "\"-Infinity\"";
	return string( x ); # shortest round-trip decimal
end

"""
	evaluate( x )

Evaluate `log1p( x )`, returning the value and the name of any exception thrown.
"""
function evaluate( x::Float64 )
	try
		return ( log1p( x ), nothing );
	catch err
		return ( nothing, string( nameof( typeof( err ) ) ) );
	end
end

"""
	libc()

Return the C library's name and version.
"""
function libc()
	if Sys.islinux()
		v = unsafe_string( ccall( :gnu_get_libc_version, Cstring, () ) );
		return "glibc $(v)";
	end
	return nothing;
end

"""
	gen( name )

Read the shared input file `name`, and write fixtures to a file of the same name.
"""
function gen( name )
	inpath = joinpath( inputs, name );
	bytes = read( inpath );
	data = JSON.parse( String( copy( bytes ) ) );
	x = Float64[ decode( v ) for v in data["x"] ];
	r = [ evaluate( v ) for v in x ];
	y = [ v[ 1 ] for v in r ];
	errors = [ v[ 2 ] for v in r ];

	meta = Dict(
		"source" => "julia::base",
		"function" => "Base.log1p",
		"implementation" => "Julia's own Float64 code, after Tang's table-driven method (base/special/log.jl)",
		"versions" => Dict( "julia" => string( VERSION ) ),
		"platform" => Dict( "os" => lowercase( string( Sys.KERNEL ) ), "arch" => string( Sys.ARCH ), "compiler" => nothing, "libc" => libc() ),
		"generated" => Dates.format( Dates.now( Dates.UTC ), "yyyy-mm-ddTHH:MM:SSZ" ),
		"inputs" => bytes2hex( SHA.sha256( bytes ) ),
		"regime" => data["regime"]
	);

	outfile = open( joinpath( dir, name ), "w" );
	write( outfile, "{\"x\":[", join( encode.( x ), "," ), "],\"expected\":[", join( encode.( y ), "," ), "]" );
	if any( e -> e !== nothing, errors )
		write( outfile, ",\"errors\":", JSON.json( errors ) );
	end
	write( outfile, ",\"meta\":", JSON.json( meta ), "}\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Shared inputs:
inputs = joinpath( dir, "..", "..", "inputs" );

for name in sort( filter( f -> endswith( f, ".json" ), readdir( inputs ) ) )
	gen( name );
end
